Script.Workflow:
module touching_list;
using system::*;
namespace demo
{
  class TouchingListItem
  {
    prop Text: string = "" {not observe}
    new (text: string) { Text = text; }
  }
}

Instance.ref.Members:
prop DragDistance: int = 0 {}
func GetMaxDragDistance(): int
{
  return deleteLabel.CachedBounds.x2 - deleteLabel.CachedBounds.x1 + 32;
}
prop MaxDragDistance: int {GetMaxDragDistance}
prop Colors: darkskin::ColorPackage = darkskin::Theme::GetColorPackage() {const, not observe}

Bounds.att.ExpectedBounds-bind:
{
              x1: -self.DragDistance;
              y1: 0;
              x2: self.CachedBounds.x2 - self.CachedBounds.x1 - self.DragDistance;
              y2: 0;
            }

Instance.ref.Members:
prop Items: observe TouchingListItem^[] = {} {const, not observe}
var serial: int = 0;
var swipeItem: TouchingListItem^ = null;
var multipleContacts: bool = false;

func GetSwipeTemplate(): TouchingListItemTemplate*
{
  if (swipeItem is null) { return null; }
  var index = Items.IndexOf(swipeItem);
  if (index == -1) { return null; }
  return cast TouchingListItemTemplate* list.Arranger.GetVisibleStyle(index);
}

func ResetSwipe(): void
{
  var row = GetSwipeTemplate();
  if (row is not null) { row.DragDistance = 0; }
  swipeItem = null;
}

func AddItems(): void
{
  for (i in range[0, 5))
  {
    serial = serial + 1;
    Items.Add(new TouchingListItem^("Item " & cast string serial
      & " — " & Sys::LoremIpsumSentence(180)));
  }
}

func BeginSwipe(arguments: GuiPointSequenceStartedEventArgs*): void
{
  ResetSwipe();
  multipleContacts = false;
  var composition = arguments.compositionSource;
  while (composition is not null and composition != list.BoundsComposition)
  {
    if (var row: TouchingListItemTemplate* = composition as TouchingListItemTemplate*)
    {
      if (row.AssociatedListControl == list) { swipeItem = row.ViewModel; }
      break;
    }
    composition = composition.Parent;
  }
}

func EndSwipe(arguments: GuiPointSequenceEndedEventArgs*): void
{
  var target = swipeItem;
  var row = GetSwipeTemplate();
  var remove = false;
  if (row is not null and not multipleContacts and arguments.reason == PointSequenceEndReason::Succeeded)
  {
    remove = row.MaxDragDistance > 0 and row.DragDistance == row.MaxDragDistance;
  }
  ResetSwipe();
  if (remove)
  {
    GuiApplication::GetApplication().InvokeInMainThread(list.RelatedControlHost, func(): void
    {
      if (Items.Contains(target)) { Items.Remove(target); }
    });
  }
}

att.BoundsComposition-set.ev.pointAction-eval:
{
                  if (arguments.eventType == GuiPointEventsType::Down and arguments.pointId != 0)
                  {
                    self.multipleContacts = true;
                    self.ResetSwipe();
                  }
                }

att.BoundsComposition-set.ev.pointGesture-eval:
{
                  if (not arguments.handled)
                  {
                    if (var scrolling : GuiPointGesture_Scrolling? = arguments.gesture as GuiPointGesture_Scrolling?)
                    {
                      if (not scrolling.isVertical)
                      {
                        arguments.selected = true;
                        arguments.handled = true;
                        if (self.swipeItem is not null and not self.multipleContacts)
                        {
                          var row = self.GetSwipeTemplate();
                          if (row is not null)
                          {
                            row.DragDistance = Math::Max(0, Math::Min(row.MaxDragDistance, row.DragDistance - scrolling.distance));
                          }
                        }
                      }
                    }
                  }
                }
